function(form) {
  var lmpDate = form.get('ANC_LMP').getValue();
  var diff = 0;

  if (lmpDate) {
    diff = Math.round((Date.now() - Date.parse(lmpDate)) / (1000 * 60 * 60 * 24));
    //var diffInWeeks = Math.ceil(diff / 7);
    var weeks = Math.floor(diff / 7);
    var days = diff % 7;
  }

  function addNineMonthsAndSevenDays(lmpDate) {
    var date = new Date(lmpDate);
    if (isNaN(date.getTime())) {
      return null; // or throw new Error("Invalid date format");
    }
    date.setMonth(date.getMonth() + 9);
    date.setDate(date.getDate() + 7);
    return date;
  }
  var resultDate = addNineMonthsAndSevenDays(lmpDate);
  if (resultDate) {
    var year = resultDate.getFullYear();
    var month = ('0' + (resultDate.getMonth() + 1)).slice(-2);
    var day = ('0' + resultDate.getDate()).slice(-2);
    var formattedDate = year + '-' + month + '-' + day;
  }
  // alert(resultDate);
  //form.get('Gestation period (weeks)').setValue(weeks + " weeks, " + days + " days");
  // alert(formattedDate);
  form.get('ANC_EDD').setValue(formattedDate);
}

function(form) {
  var multi_select = form.get('ANC_Any_Other_Problems').currentRecord.value.value;
  var length = multi_select == undefined ? 0 : multi_select.length;
  var arr = []
  if (length == 0) {
    form.get("ANC_other_diagnosis").setHidden(true);
  } else {
    for (var i = 0; i < length; i++) {
      var name = multi_select[i].displayString == undefined ? multi_select[i].name : multi_select[i].displayString;
      arr.push(name);
      if (arr.includes('Other_Diagnosis'))
        form.get("ANC_other_diagnosis").setHidden(false);
      else
        form.get("ANC_other_diagnosis").setHidden(true);
    }
  }
}

function(form) {
  if (form.get('Subscription card').getValue() === 'Yes') {
    form.get('Subscription card Numbers').setHidden(false);
  } else {
    form.get('Subscription card Numbers').setHidden(true);
  }
}

events.onFormInit:
function(form) {
  form.get('RF_Date_Of_Scheduled').setHidden(true);
  form.get('RF_Outcome_Section').setHidden(true);
  form.get('RF_Other_Institution').setHidden(true);
  form.get('ANC_other_diagnosis').setHidden(true);
  form.get('ANC_HIV').setHidden(true);

  var ht = form.get('ANC_HEIGHT').getValue();
  var wt = form.get('ANC-WEIGHT').getValue();

  if (ht && wt) {
    form.get('ANC_BMI').setValue(((parseFloat(wt) / parseFloat(ht) / parseFloat(ht)) * 10000).toFixed(1));
  }
}
